import json

# Final verification
with open('outputs/02c_PARTIAL_W7B8_1771259718.json', 'r') as f:
    data = json.load(f)

items = data['checklist_with_code']

# Comprehensive check
print("=== Output Validation ===")
print(f"Total items: {len(items)}")

# Check schema compliance
errors = []
for i, item in enumerate(items[:5], 1):  # Check first 5 in detail
    if 'code_scope' not in item:
        errors.append(f"Item {i}: missing code_scope")
    else:
        cs = item['code_scope']
        if 'locations' not in cs:
            errors.append(f"Item {i}: missing code_scope.locations")
        if 'resolution_status' not in cs:
            errors.append(f"Item {i}: missing code_scope.resolution_status")
        if 'resolution_error' not in cs:
            errors.append(f"Item {i}: missing code_scope.resolution_error")
        if not isinstance(cs.get('locations', []), list):
            errors.append(f"Item {i}: locations is not a list")

    if 'code_excerpt' not in item:
        errors.append(f"Item {i}: missing code_excerpt")

    # Check original fields preserved
    required_originals = ['check_id', 'property_id', 'title', 'severity']
    for field in required_originals:
        if field not in item:
            errors.append(f"Item {i}: missing original field {field}")

if errors:
    print(f"\n✗ Found {len(errors)} errors:")
    for err in errors:
        print(f"  - {err}")
else:
    print("\n✓ Schema validation passed")

# Count statuses
status_counts = {}
for item in items:
    status = item['code_scope']['resolution_status']
    status_counts[status] = status_counts.get(status, 0) + 1

print(f"\n=== Resolution Statistics ===")
for status, count in sorted(status_counts.items()):
    print(f"{status}: {count}")

print(f"\n✓ Output file valid and complete")

PYEOF
